//! OpenChamber palettes resolved from the canonical theme definitions.
//!
//! `resources/themes.json` is generated by `bun run native:resources` from the
//! same resolver the web UI uses, so every color here is the value the
//! Electron client paints. Views read [`Palette`]; GPUI Kit components read the
//! Kit theme, which [`apply`] fills from the same palette.

use std::collections::HashMap;

use gpui_kit::component::Theme;
use gpui_kit::component::theme::ThemeMode;
use gpui_kit::{App, Global, Hsla, Rgba};
use serde::Deserialize;

const THEMES_JSON: &str = include_str!("../resources/themes.json");

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ThemeFile {
    default_light: String,
    default_dark: String,
    themes: Vec<ThemeEntry>,
}

#[derive(Deserialize)]
struct ThemeEntry {
    id: String,
    variant: String,
    colors: HashMap<String, String>,
}

/// Light or dark appearance.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Appearance {
    Light,
    Dark,
}

/// The semantic colors native views paint with.
#[derive(Clone, Debug, PartialEq)]
pub struct Palette {
    pub id: String,
    pub appearance: Appearance,
    pub background: Hsla,
    pub foreground: Hsla,
    pub muted: Hsla,
    pub muted_foreground: Hsla,
    pub elevated: Hsla,
    pub elevated_foreground: Hsla,
    pub subtle: Hsla,
    pub border: Hsla,
    pub hover: Hsla,
    pub active: Hsla,
    pub selection: Hsla,
    pub selection_foreground: Hsla,
    pub focus_ring: Hsla,
    pub primary: Hsla,
    pub primary_foreground: Hsla,
    pub primary_hover: Hsla,
    pub chat_background: Hsla,
    pub user_message_background: Hsla,
    pub divider: Hsla,
    pub link: Hsla,
    pub inline_code: Hsla,
    pub syntax_background: Hsla,
    pub syntax_foreground: Hsla,
    pub error: Hsla,
    pub warning: Hsla,
    pub success: Hsla,
    pub info: Hsla,
    /// Solid status fills, for surfaces such as the close button's hover.
    pub status_error: Hsla,
    pub status_error_foreground: Hsla,
    pub status_success: Hsla,
    pub cursor: Hsla,
}

impl Global for Palette {}

impl Palette {
    /// The default palette for an appearance.
    pub fn default_for(appearance: Appearance) -> Self {
        let file = theme_file();
        let id = match appearance {
            Appearance::Light => &file.default_light,
            Appearance::Dark => &file.default_dark,
        };
        Self::by_id(id).expect("the generated themes include both default palettes")
    }

    /// A built-in palette by its theme ID.
    pub fn by_id(id: &str) -> Option<Self> {
        let file = theme_file();
        let entry = file.themes.iter().find(|entry| entry.id == id)?;
        let color = |token: &str| -> Hsla {
            let value = entry
                .colors
                .get(token)
                .unwrap_or_else(|| panic!("generated theme {} lacks the {token} token", entry.id));
            parse_hex(value).unwrap_or_else(|| panic!("theme {} has a non-hex {token}", entry.id))
        };
        Some(Self {
            id: entry.id.clone(),
            appearance: if entry.variant == "dark" {
                Appearance::Dark
            } else {
                Appearance::Light
            },
            background: color("surface.background"),
            foreground: color("surface.foreground"),
            muted: color("surface.muted"),
            muted_foreground: color("surface.mutedForeground"),
            elevated: color("surface.elevated"),
            elevated_foreground: color("surface.elevatedForeground"),
            subtle: color("surface.subtle"),
            border: color("interactive.border"),
            hover: color("interactive.hover"),
            active: color("interactive.active"),
            selection: color("interactive.selection"),
            selection_foreground: color("readable.selectionForeground"),
            focus_ring: color("interactive.focusRing"),
            primary: color("primary.base"),
            primary_foreground: color("primary.foreground"),
            primary_hover: color("primary.hover"),
            chat_background: color("chat.background"),
            user_message_background: color("chat.userMessageBackground"),
            divider: color("chat.divider"),
            link: color("markdown.link"),
            inline_code: color("markdown.inlineCode"),
            syntax_background: color("syntax.base.background"),
            syntax_foreground: color("syntax.base.foreground"),
            error: color("readable.status.error"),
            warning: color("readable.status.warning"),
            success: color("readable.status.success"),
            info: color("readable.status.info"),
            status_error: color("status.error"),
            status_error_foreground: color("status.errorForeground"),
            status_success: color("status.success"),
            cursor: color("interactive.cursor"),
        })
    }
}

/// Installs `palette` for native views and GPUI Kit components.
pub fn apply(palette: Palette, cx: &mut App) {
    let mode = match palette.appearance {
        Appearance::Light => ThemeMode::Light,
        Appearance::Dark => ThemeMode::Dark,
    };
    // Changing the mode reloads the Kit's own colors, so colors are written
    // in a second update.
    Theme::change(mode, None, cx);
    Theme::update(cx, |theme| {
        theme.background = palette.background;
        theme.foreground = palette.foreground;
        theme.border = palette.border;
        theme.input = palette.border;
        theme.ring = palette.focus_ring;
        theme.caret = palette.cursor;
        theme.selection = palette.selection;
        theme.muted = palette.muted;
        theme.muted_foreground = palette.muted_foreground;
        theme.accent = palette.hover;
        theme.accent_foreground = palette.foreground;
        theme.primary = palette.primary;
        theme.primary_hover = palette.primary_hover;
        theme.primary_foreground = palette.primary_foreground;
        theme.secondary = palette.elevated;
        theme.secondary_hover = palette.hover;
        theme.secondary_foreground = palette.elevated_foreground;
        theme.popover = palette.elevated;
        theme.popover_foreground = palette.elevated_foreground;
        theme.sidebar = palette.muted;
        theme.sidebar_foreground = palette.foreground;
        theme.sidebar_border = palette.border;
        theme.sidebar_accent = palette.selection;
        theme.sidebar_accent_foreground = palette.selection_foreground;
        theme.list_hover = palette.hover;
        theme.list_active = palette.selection;
        theme.link = palette.link;
        theme.danger = palette.error;
        theme.warning = palette.warning;
        theme.success = palette.success;
        theme.info = palette.info;
        theme.scrollbar_thumb = palette.active;
        theme.scrollbar_thumb_hover = palette.border;
        theme.window_border = palette.border;
    });
    cx.set_global(palette);
}

fn theme_file() -> ThemeFile {
    serde_json::from_str(THEMES_JSON).expect("resources/themes.json is generated valid JSON")
}

/// Parses `#rgb`, `#rgba`, `#rrggbb` and `#rrggbbaa`.
fn parse_hex(value: &str) -> Option<Hsla> {
    let digits = value.strip_prefix('#')?;
    let expanded: String = match digits.len() {
        3 | 4 => digits.chars().flat_map(|digit| [digit, digit]).collect(),
        6 | 8 => digits.to_owned(),
        _ => return None,
    };
    let channel = |index: usize| -> Option<f32> {
        let byte = u8::from_str_radix(expanded.get(index * 2..index * 2 + 2)?, 16).ok()?;
        Some(f32::from(byte) / 255.0)
    };
    let alpha = if expanded.len() == 8 {
        channel(3)?
    } else {
        1.0
    };
    Some(Hsla::from(Rgba {
        r: channel(0)?,
        g: channel(1)?,
        b: channel(2)?,
        a: alpha,
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_every_hex_form() {
        let opaque = parse_hex("#ff0000").expect("valid");
        assert!((opaque.a - 1.0).abs() < f32::EPSILON);
        let translucent = parse_hex("#ffffff0f").expect("valid");
        assert!((translucent.a - 15.0 / 255.0).abs() < 1e-6);
        assert!(parse_hex("#abc").is_some());
        assert!(parse_hex("red").is_none());
        assert!(parse_hex("#12345").is_none());
    }

    #[test]
    fn every_generated_theme_resolves() {
        let file = theme_file();
        assert!(file.themes.len() > 2);
        for entry in &file.themes {
            let palette = Palette::by_id(&entry.id).expect("theme exists");
            assert_eq!(palette.id, entry.id);
        }
        assert_eq!(
            Palette::default_for(Appearance::Dark).appearance,
            Appearance::Dark
        );
        assert_eq!(
            Palette::default_for(Appearance::Light).appearance,
            Appearance::Light
        );
    }
}
